    countries,
    activeYears,
    record,
    trophies,
    prevPlayer,
    nextPlayer,
    isAuthenticated = false,
    isAdmin = false,
    playerData,
    onSendEmail,
}: Props) => {
    const playerCardsGridColSpan = { base: 12, sm: 6, lg: 3 };

    return (
        <Container size="xl">
            <Stack
                gap="sm"
                w="100%"
            >
                <Grid
                    type="container"
                    mb="lg"
                    gap="xs"
                    align="center"
                >
                    <Grid.Col
                        span="content"
