                                order={1}
                                title={player.name}
                                year={year}
                                validYears={activeYears}
                            />
                        </Center>
                    </Grid.Col>
                    <Grid.Col
                        span="content"
                        align="center"
                    >
                        {nextPlayer ? (
                            <PlayerLink
                                player={nextPlayer}
                                year={year}
                                format="right-arrow"
                            />
                        ) : (
                            <Box
                                data-testid="player-next-placeholder"
                                aria-hidden="true"
                            />
                        )}
                    </Grid.Col>
                </Grid>
                <Grid
                    type="container"
                    breakpoints={{
                        xs: '24em',
                        sm: '36em',
                        md: '54em',
                        lg: '74em',
                        xl: '88em',
                    }}
                >
                    <Grid.Col span={playerCardsGridColSpan}>
                        <PlayerCard
                            player={player}
                            clubs={clubs}
                            countries={countries}
                            trophies={trophies}
                        />
                    </Grid.Col>
                    <Grid.Col span={playerCardsGridColSpan}>
                        <PlayerInfo
                            player={player}
                            year={year}
                            introducedBy={introducedBy}
                            lastPlayed={lastPlayed}
                            lastWon={lastWon}
                            isAuthenticated={isAuthenticated}
                            isAdmin={isAdmin}
                            playerData={playerData}
                            onSendEmail={onSendEmail}
                        />
                    </Grid.Col>
                    <Grid.Col span={playerCardsGridColSpan}>
                        <PlayerResults
                            player={player}
                            year={year}
                            record={record}
                        />
                    </Grid.Col>
                    <Grid.Col span={playerCardsGridColSpan}>
                        <PlayerPositions
                            player={player}
                            year={year}
                            record={record}
                        />
                    </Grid.Col>
                </Grid>
                <Group>
                    <Paper
                        p="sm"
                        w="auto"
                        style={{ flex: '1' }}
                    >
                        <PlayerHeatmap
                            data={history}
                            year={year}
                        />
                    </Paper>
                </Group>
            </Stack>
        </Container>
    );
};

